/**
 * Centralised, type-safe runtime configuration.
 *
 * All environment-driven values used by the frontend MUST be read from this
 * module — never `import.meta.env.*` directly in feature code. This guarantees
 * a single place to validate, default, and document every required variable
 * when the project is duplicated and pointed at a fresh Supabase instance.
 *
 * NOTE: `src/integrations/supabase/client.ts` is auto-generated by Lovable
 * and is the only file allowed to inline the project ref + publishable key.
 * For a new deployment Lovable rewrites that file from the connected
 * Supabase project; for self-hosting, the values below are the canonical
 * runtime source.
 */

type EnvShape = {
  supabaseUrl: string;
  supabasePublishableKey: string;
  supabaseProjectId: string;
  /** Cloudflare R2 public base, e.g. https://cdn.example.com (no trailing slash). */
  r2PublicBaseUrl: string;
};

function read(name: string, fallback = ""): string {
  const v = (import.meta.env as Record<string, string | undefined>)[name];
  return (v ?? fallback).replace(/\/$/, "");
}

export const env: EnvShape = {
  supabaseUrl: read("VITE_SUPABASE_URL"),
  supabasePublishableKey: read("VITE_SUPABASE_PUBLISHABLE_KEY"),
  supabaseProjectId: read("VITE_SUPABASE_PROJECT_ID"),
  r2PublicBaseUrl: read("VITE_R2_PUBLIC_BASE_URL"),
};

/**
 * Validate at module load. Missing values throw immediately so a misconfigured
 * deployment fails loud instead of silently calling a wrong backend.
 * Skipped in test environments where the values are irrelevant.
 */
if (import.meta.env.MODE !== "test") {
  const missing = (Object.entries(env) as Array<[keyof EnvShape, string]>)
    .filter(([, v]) => !v)
    .map(([k]) => k);
  if (missing.length > 0) {
    // eslint-disable-next-line no-console
    console.warn(
      `[config] Missing required env vars: ${missing.join(", ")}. ` +
        `Set them in .env (see .env.example).`,
    );
  }
}
